      input CredentialWriteInput;
      output CredentialView;
      fails Expired;
      fails Invalid;
      requires atomic;
      expose command at "/refresh";
      workflow {
        load Credential by input.token as found for update else Invalid;
        validate found.used == false else Invalid;
        validate found.expiresAt > now() else Expired;
        update found { used: true; }
        persist found;
        create Credential as made {
          owner: found.owner;
          used: false;
          expiresAt: now() + 7 days;
        }
        persist made;
        return made;
      }
    }

    capability Touch {
      input CredentialWriteInput;
      output CredentialView;
      fails Invalid;
      requires atomic;
      expose command at "/touch";
      workflow {
        load Credential by input.token as found for update else Invalid;
        validate found.owner == actor else Invalid;
        update found { used: true; }
        persist found;
        return found;
      }
    }

    capability Register {
      input RegisterInput;
      output AccountView;
      requires atomic;
      expose command at "/register";
      workflow {
        create Account as made {
          name: input.name;
          passwordHash: input.password;
        }
        persist made;
        return made;
      }
    }

    capability Login {
      input LoginInput;
      output AccountView;
      fails BadLogin;
      requires readonly;
      expose command at "/login";
      workflow {
        load Account by name: input.name as found else BadLogin;
        validate found.passwordHash matches input.password else BadLogin;
        return found;
      }
    }

    capability FindAccount {
      input FindAccountInput;
      output AccountView;
      fails AccountNotFound;
      requires readonly;
      expose query at "/find-account";
      workflow {
        load Account by name: input.name as found else AccountNotFound;
        return found;
      }
    }
  }
